using System;using System.Threading.Tasks;using UnityEngine;using UnityEngine.SceneManagement;using Demo5.FrontEnd;
public static class VerifyFacilityGrowth {
 static SettlementController C()=>UnityEngine.Object.FindAnyObjectByType<SettlementController>();static SettlementDevelopmentWorld W()=>UnityEngine.Object.FindAnyObjectByType<SettlementDevelopmentWorld>();
 static void Check(bool ok,string msg){if(!ok)throw new Exception(msg);}
 public static async Task<string> Temporary(){var c=C();c.Development.State.Warehouse=0;c.Development.State.Research=false;await Task.Delay(200);var w=W();Check(w.TemporaryStock.activeSelf&&!w.StorageCrates.activeSelf&&!w.ResearchTable.activeSelf&&w.ResearchPlan.activeSelf,"Temporary visibility");Check(c.Cabinet.GetComponent<SettlementFacilityFocus>().UseUnrestored,"Temporary hit path");return "Preview fixture: temporary stock bundle and research plan visible; no crates/table.";}
 public static async Task<string> Restored(){var c=C();c.Development.State.Warehouse=1;await Task.Delay(200);var w=W();Check(!w.TemporaryStock.activeSelf&&w.StorageCrates.activeSelf&&!w.WarehouseUpgrade.activeSelf,"Level1 visibility");Check(!c.Cabinet.GetComponent<SettlementFacilityFocus>().UseUnrestored,"Restored path");return "PASS warehouse level1 visible without reinforced hardware.";}
 public static async Task<string> Upgraded(){var c=C();c.Development.State.Warehouse=2;c.Development.State.Research=true;await Task.Delay(200);Check(W().WarehouseUpgrade.activeSelf&&W().ResearchTable.activeSelf&&!W().ResearchPlan.activeSelf,"Upgrade visibility");var data=CampaignPersistence.Capture(c);CampaignPersistence.Prepare(data,c);SceneManager.LoadScene("Settlement");await Task.Delay(650);Check(W().WarehouseUpgrade.activeInHierarchy&&W().ResearchTable.activeSelf&&!W().TemporaryStock.activeSelf&&!W().ResearchPlan.activeSelf,"Restore visual state");return "PASS level2 and research complete; save-data capture/restore preserves visuals. In-memory fixture only, no save slot written.";}
}
